import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import ProductForm from "./components/product/ProductForm";
import ProductList from "./components/product/ProductList";
import EmployeeForm from "./components/employee/EmployeeForm";
import EmployeeList from "./components/employee/EmployeeList";
import UserForm from "./components/user/UserForm";
import UserList from "./components/user/UserList";
import Layout from "./components/layout";
import Login from "./components/login/Login";
import ProtectedRoute from "./components/login/ProtectedRoute";
import AdminRoute from "./components/login/AdminRoute";
import { useEffect } from "react";
import { setAuthToken } from "./redux/root/api";

function App() {
  useEffect(() => {
    const token = localStorage.getItem("token");
    if (token) setAuthToken(token);
  }, []);

  return (
    <Router>
      <Routes>
        {/* Public route */}
        <Route path="/login" element={<Login />} />

        {/* Protected routes */}
        <Route
          path="/"
          element={
            <ProtectedRoute>
              <Layout>
                <EmployeeList />
              </Layout>
            </ProtectedRoute>
          }
        />

        <Route
          path="/add"
          element={
            <ProtectedRoute>
              <Layout>
                <EmployeeForm />
              </Layout>
            </ProtectedRoute>
          }
        />

        <Route
          path="/edit/:id"
          element={
            <ProtectedRoute>
              <Layout>
                <EmployeeForm />
              </Layout>
            </ProtectedRoute>
          }
        />

        <Route
          path="/products"
          element={
            <ProtectedRoute>
              <Layout>
                <ProductList />
              </Layout>
            </ProtectedRoute>
          }
        />

        <Route
          path="/products/add"
          element={
            <ProtectedRoute>
              <Layout>
                <ProductForm />
              </Layout>
            </ProtectedRoute>
          }
        />

        {/* Admin-only routes - only accessible to ROLE_ADMIN */}
        <Route
          path="/users"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserList />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />

        <Route
          path="/users/add"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserForm />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />

        <Route
          path="/users/edit/:id"
          element={
            <ProtectedRoute>
              <AdminRoute>
                <Layout>
                  <UserForm />
                </Layout>
              </AdminRoute>
            </ProtectedRoute>
          }
        />
      </Routes>
    </Router>
  );
}

export default App;
